<div><dt><?= $serviceCopy('مصدر مفتاح التشفير','Encryption key source') ?></dt><dd><?= $serviceDiagnostics['key_source'] === 'environment' ? $serviceCopy('بيئة الخادم','Server environment') : $serviceCopy('ملف محلي خاص بالخادم','Private server file') ?></dd></div>
<div><dt><?= $serviceCopy('رابط البريد العام','Public email link base') ?></dt><dd><bdi><?= $serviceDiagnostics['base_url_state'] === 'configured' ? e($serviceDiagnostics['base_url']) : $serviceCopy('غير محدد أو غير صالح','Missing or invalid') ?></bdi> · <?= $serviceDiagnostics['base_url_https'] ? 'HTTPS' : $serviceCopy('يتطلب HTTPS للإنتاج','HTTPS required in production') ?></dd></div></dl>
<?php if (in_array('unreadable',[$serviceDiagnostics['smtp'],$serviceDiagnostics['recipient'],$serviceDiagnostics['dorar']],true)): ?><p class="notice notice-error"><?= $serviceCopy('تعذرت قراءة إعداد مشفر. استعد مفتاحه الأصلي قبل تغييره؛ القيم الحالية محفوظة.','An encrypted setting cannot be read. Restore its original key before editing; the current values are preserved.') ?></p><?php endif; ?></article>
<article class="knowledge-card admin-service-card"><h3><?= $serviceCopy('بريد Gmail','Gmail email') ?></h3><p class="source-note"><?= $serviceCopy('استخدم App Password وحسابًا مصرحًا به. الاختبار اختياري ويرسل رسالة واحدة فقط إلى المستلم المصرح به، بحد اختبار واحد للحساب كل ساعة.','Use an App Password for an authorized account. An optional test sends one message to the authorized recipient, with one attempt per Owner per clock hour.') ?></p>
<form class="form-stack" method="post" action="/admin#admin-services" data-gmail-form><?= csrf_field() ?><input type="hidden" name="kind" value="gmail-settings">
<label><?= $serviceCopy('بريد Gmail','Gmail account email') ?><input type="email" name="gmail_email" dir="ltr" maxlength="190" value="<?= e($adminError !== '' && ($_POST['kind'] ?? '') === 'gmail-settings' && is_string($_POST['gmail_email'] ?? null) ? mb_substr($_POST['gmail_email'],0,190,'UTF-8') : $smtpConfig['smtp_username']) ?>" autocomplete="username" required></label>
<label>App Password<input type="password" name="smtp_password" dir="ltr" maxlength="500" autocomplete="new-password" <?= $serviceDiagnostics['smtp'] === 'missing' ? 'required' : '' ?>><small><?= $serviceCopy('اتركه فارغًا للاحتفاظ بالكلمة المحفوظة للحساب نفسه.','Leave blank to keep the stored password for the same account.') ?></small></label>
<label><?= $serviceCopy('مستلم اختبار جديد (اختياري)','New test recipient (optional)') ?><input type="email" name="test_recipient" dir="ltr" maxlength="190" autocomplete="off"><small><?= $serviceCopy('الفراغ يحتفظ بالمستلم المحفوظ.','Blank retains the saved recipient.') ?></small></label>
<label class="check-label"><input type="checkbox" name="test_recipient_authorized"><?= $serviceCopy('صاحب عنوان الاختبار الجديد مصرح له باستلام هذه الرسالة.','The new test recipient is authorized to receive this message.') ?></label>
<?php if ($serviceDiagnostics['recipient'] !== 'missing'): ?><label class="check-label"><input type="checkbox" name="clear_test_recipient"><?= $serviceCopy('إزالة مستلم الاختبار المحفوظ (له الأولوية)','Remove the stored test recipient (takes priority)') ?></label><?php endif; ?>
<label><?= $serviceCopy('كلمة مرور المالك الحالية','Current Owner password') ?><input type="password" name="owner_password" maxlength="500" autocomplete="current-password" required></label>
<div class="hero-actions"><button class="button button-primary"><?= $serviceCopy('حفظ الإعدادات','Save settings') ?></button><button class="button button-secondary" name="send_test_email" value="1"><?= $serviceCopy('حفظ وإرسال اختبار واحد','Save and send one test') ?></button></div></form></article>
<article class="knowledge-card admin-service-card"><h3><?= $serviceCopy('بحث الدرر السنية','Dorar search') ?></h3><p class="source-note"><?= $serviceCopy('استخدم الرمز الرسمي بعد الموافقة. حذف الرمز المحفوظ لا يزيل رمزًا محددًا في بيئة الخادم.','Use the officially approved token. Clearing a stored token leaves any server environment token active.') ?></p>
<form class="form-stack" method="post" action="/admin#admin-services" data-dorar-form><?= csrf_field() ?><input type="hidden" name="kind" value="dorar-settings"><label><?= $serviceCopy('رمز API الجديد (اختياري)','New API token (optional)') ?><input type="password" name="dorar_api_token" maxlength="500" autocomplete="new-password"></label>
<?php if ($serviceDiagnostics['dorar'] !== 'missing'): ?><label class="check-label"><input type="checkbox" name="clear_dorar_token"><?= $serviceCopy('حذف الرمز المحفوظ صراحةً','Explicitly clear the stored token') ?></label><?php endif; ?>
<label><?= $serviceCopy('كلمة مرور المالك الحالية','Current Owner password') ?><input type="password" name="owner_password" maxlength="500" autocomplete="current-password" required></label><button class="button button-secondary"><?= $serviceCopy('حفظ إعدادات الدرر','Save Dorar settings') ?></button></form></article>
